(() => { const a = window.__CITY_APP, C = window.CITY, DV = C.DON_VALLEY, B = DV.boxes.find((b) => b.kind === 'high-park'), M = 100;
  const out = (x, z) => x < B.x0 - M || x > B.x1 + M || z < B.z0 - M || z > B.z1 + M;
  // the static scene outside the box (100 m clear of it): each named mesh's vertices or instances there, counted and summed
  const fp = {}; const v = new a.scene.position.constructor();
  a.scene.updateMatrixWorld(true);
  a.scene.traverse((o) => { if (!o.isMesh || !o.geometry || !o.geometry.attributes.position) return; if (/^(HighPark|Colborne)/.test(o.name) || /HighParkFeature/.test(o.parent && o.parent.name || '')) return;
    const k = (o.parent && o.parent.name ? o.parent.name + '/' : '') + (o.name || o.type); let n = 0, s = 0;
    if (o.isInstancedMesh) { const e = o.instanceMatrix.array; for (let i = 0; i < o.count; i++) { const x = e[i * 16 + 12], z = e[i * 16 + 14]; if (out(x, z)) { n++; s += Math.round(x * 10) + Math.round(e[i * 16 + 13] * 10) * 3 + Math.round(z * 10) * 7; } } }
    else { const p = o.geometry.attributes.position, m = o.matrixWorld.elements; for (let i = 0; i < p.count; i++) { const x = p.getX(i) * m[0] + p.getY(i) * m[4] + p.getZ(i) * m[8] + m[12], z = p.getX(i) * m[2] + p.getY(i) * m[6] + p.getZ(i) * m[10] + m[14]; if (out(x, z)) { n++; s += Math.round(x * 10) + Math.round((p.getX(i) * m[1] + p.getY(i) * m[5] + p.getZ(i) * m[9] + m[13]) * 10) * 3 + Math.round(z * 10) * 7; } } }
    if (n) { const f = fp[k] || (fp[k] = [0, 0, 0]); f[0]++; f[1] += n; f[2] += s; } });
  const t = a.trafficSystem, inPark = (o) => DV.inBox(o.x, o.z);
  const closedNear = (x, z) => (t.network?.edges || []).some((e) => e.parkClosed && Math.hypot(e.sx + e.dx * e.len / 2 - x, e.sz + e.dz * e.len / 2 - z) < e.len / 2 + 2 && Math.abs((x - e.sx) * e.dz - (z - e.sz) * e.dx) < 6);
  const cars = (t.cars || []).filter((c) => Number.isFinite(c.x) && inPark(c));
  return { features: C.highParkFeatureStats || null, roads: C.highParkRoadStats || null, info: a.renderer.info.render, readyMs: a.startupReadyMs || null,
    heapMB: performance.memory ? Math.round(performance.memory.usedJSHeapSize / 1048576) : null,
    carsInPark: cars.length, carsOnClosedRoads: cars.filter((c) => closedNear(c.x, c.z)).length, fingerprint: fp }; })()

